/** Verify checks — smoke contracts, not a test framework (0007 §verify). */
export type Verify = {
    kind: "binary_runs";
    path: string;
    args?: string[];
} | {
    kind: "file_exists";
    path: string;
} | {
    kind: "shell";
    script: string;
};
/** A built binary runs (default sanity: `--version`-style). */
export declare function verifyBinary(path: string, args?: string[]): Verify;
export declare function verifyFile(path: string): Verify;
export declare function verifyShell(script: string): Verify;
